\begin{tikzpicture}[font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\pgfmathsetmacro{\diag}{4*cos(37)}
\pgfmathsetmacro{\height}{sqrt(\diag*\diag-9)}
