\coordinate (A) at (0,0);
\coordinate (B) at (3,0);
\coordinate (C) at (3,\height);
\coordinate (D) at ({4*cos(\thetaA+37)},{4*sin(\thetaA+37)});
\draw[black,line width=0.8pt] (A)--(B)--(C)--(D)--cycle (A)--(C);
\coordinate (Bm1) at ($(B)!0.3cm!(A)$);
\coordinate (Bm2) at ($(B)!0.3cm!(C)$);
\draw[black,line width=0.4pt] (Bm1)--($(Bm1)+(Bm2)-(B)$)--(Bm2);
\pic[draw=black,line width=0.4pt,angle radius=0.3cm] {right angle=A--C--D};
\pic[draw=black,line width=0.4pt,angle radius=0.7cm] {angle=B--A--C};
\pic[draw=black,line width=0.4pt,angle radius=0.95cm] {angle=C--A--D};
\node at ({0.95*cos(\thetaA/2)},{0.95*sin(\thetaA/2)}) {$\theta$};
\node at ({1.25*cos(\thetaA+18.5)},{1.25*sin(\thetaA+18.5)}) {$37^\circ$};
\path (A)--(B) node[midway,below] {$3$};
\path (A)--(D) node[midway,left] {$4$};
\end{tikzpicture}

